        uint256 _ethPriceInCurrency = feed.lastGoodPrice(); // dec18 // All Yamato funcs uses fetchPrice before hand and so you can use lastGoodPrice here.
        uint256 _coll = _pledge.coll; // dec18
        uint256 _debt = _pledge.debt; // dec18
